// First denied debit only. This record is diagnostic, never a permit or reset.
// The owner itself retains it; no external ledger or imported state is used.
struct budget_failure_note final {
  counter kind = counter::work;
  phase state = phase::disabled;
  bool present = false;
  std::uint64_t used = 0, requested = 0, cap = 0;
};
static_assert (sizeof (budget_failure_note) <= 32, "bounded first-denial record");
struct usage {

if (used == nullptr) return fail (failure::budget);
if (*used > cap || amount > cap - *used) {
  // No subtraction wraps: the right operand is not evaluated if used>cap.
  // Invalid owners returned above, so the first denied debit is immutable.
  m_budget_failure = {kind, m_phase, true, *used, amount, cap};
  return fail (failure::budget);
}
*used += amount; return true;
